-- email_templates: 29 row(s)
INSERT INTO `email_templates` (`id`, `workspaceId`, `key`, `name`, `subject`, `body`, `variables`, `enabled`, `updatedAt`) VALUES
('cmuojlbrc00h1uz7d652trjms', 'cmuojlaux0000uz7de9mahyza', 'welcome', 'Welcome email', 'Welcome to {{business_name}}, {{client_name}}', 'Hi {{client_name}},\n\nYour account is ready. From your portal you can start a project, upload files, review edits and pay invoices — all in one place.\n\nPlease confirm your email address so we can connect your account to any projects we\'ve set up for you:\n\n[[Confirm email|{{verify_url}}]]\n\nIf you didn\'t create this account, you can ignore this message.', '[\"client_name\",\"verify_url\",\"dashboard_url\"]', 1, '2026-09-30 20:12:56.136'),
('cmuojlbrg00h2uz7dm3ssv1ei', 'cmuojlaux0000uz7de9mahyza', 'magic_link', 'Magic sign-in link', 'Your sign-in link for {{business_name}}', 'Hi {{client_name}},\n\nUse the button below to sign in. The link works once and expires in 15 minutes.\n\n[[Sign in|{{magic_url}}]]\n\nIf you didn\'t request this, you can safely ignore it.', '[\"client_name\",\"magic_url\"]', 1, '2026-09-30 20:12:56.140'),
('cmuojlbri00h3uz7dv1sdb8y6', 'cmuojlaux0000uz7de9mahyza', 'password_reset', 'Password reset', 'Reset your {{business_name}} password', 'Hi {{client_name}},\n\nWe received a request to reset your password. The link below is valid for one hour.\n\n[[Choose a new password|{{reset_url}}]]\n\nIf you didn\'t ask for this, no action is needed.', '[\"client_name\",\"reset_url\"]', 1, '2026-09-30 20:12:56.143'),
('cmuojlbrp00h4uz7d7caypmx3', 'cmuojlaux0000uz7de9mahyza', 'invite', 'Portal invite', 'You\'re invited to {{business_name}}', 'Hi {{client_name}},\n\nYou\'ve been invited to {{business_name}}. Set your password to access your projects, files and invoices.\n\n[[Accept invite|{{invite_url}}]]\n\nThis invite is valid for 7 days.', '[\"client_name\",\"invite_url\"]', 1, '2026-09-30 20:12:56.149'),
('cmuojlbrs00h5uz7d8a6vg2lt', 'cmuojlaux0000uz7de9mahyza', 'lead_received', 'Lead received (confirmation)', 'We\'ve received your project request ({{request_id}})', 'Hi {{client_name}},\n\nThanks for your request — it\'s in. Here\'s what you sent:\n\nRequest ID: {{request_id}}\nProject type: {{project_type}}\nExpected response: {{response_time}}\n\nWhat happens next: we\'ll review your details and reply with next steps — usually a short call or a fixed-scope quote.\n\nKeep your request ID handy if you need to reach us.', '[\"client_name\",\"request_id\",\"project_type\",\"response_time\"]', 1, '2026-09-30 20:12:56.152'),
('cmuojlbru00h6uz7d0zlfaq3p', 'cmuojlaux0000uz7de9mahyza', 'contact_received', 'Contact form received', 'Thanks for getting in touch', 'Hi {{client_name}},\n\nThanks for your message — we\'ll get back to you within one business day.\n\n— {{business_name}}', '[\"client_name\"]', 1, '2026-09-30 20:12:56.154'),
('cmuojlbrx00h7uz7d0pipisdw', 'cmuojlaux0000uz7de9mahyza', 'meeting_booked', 'Meeting booked', 'Confirmed: {{meeting_type}} on {{meeting_time}}', 'Hi {{client_name}},\n\nYour {{meeting_type}} is confirmed for {{meeting_time}}.\n\n[[Join the meeting|{{meeting_url}}]]\n\nNeed to reschedule? Just reply to this email.', '[\"client_name\",\"meeting_type\",\"meeting_time\",\"meeting_url\"]', 1, '2026-09-30 20:12:56.157'),
('cmuojlbrz00h8uz7d8084ksuw', 'cmuojlaux0000uz7de9mahyza', 'quote_sent', 'Quote sent', 'Your quote {{quote_number}} is ready', 'Hi {{client_name}},\n\nYour quote for {{project_name}} is ready to review — {{amount}}.\n\n[[Review your quote|{{quote_url}}]]\n\nYou can accept it in one click, or reply with any questions.', '[\"client_name\",\"project_name\",\"amount\",\"quote_number\",\"quote_url\"]', 1, '2026-09-30 20:12:56.159'),
('cmuojlbs200h9uz7do1uwnwtv', 'cmuojlaux0000uz7de9mahyza', 'quote_accepted', 'Quote accepted', 'Thanks — quote {{quote_number}} accepted', 'Hi {{client_name}},\n\nThanks for accepting quote {{quote_number}} for {{project_name}}. Next we\'ll send the agreement for your signature.\n\n[[Open your project|{{project_url}}]]', '[\"client_name\",\"project_name\",\"quote_number\",\"project_url\"]', 1, '2026-09-30 20:12:56.162'),
('cmuojlbs400hauz7d5g4dbqwv', 'cmuojlaux0000uz7de9mahyza', 'contract_sent', 'Contract sent', 'Your agreement for {{project_name}} is ready to sign', 'Hi {{client_name}},\n\nYour agreement for {{project_name}} is ready. Please review and sign so we can lock in your slot.\n\n[[Review & sign|{{contract_url}}]]', '[\"client_name\",\"project_name\",\"contract_url\"]', 1, '2026-09-30 20:12:56.164'),
('cmuojlbs700hbuz7dj15jkx3h', 'cmuojlaux0000uz7de9mahyza', 'contract_signed', 'Contract signed', 'Agreement signed — next step: payment', 'Hi {{client_name}},\n\nThank you for signing the agreement for {{project_name}}. Your invoice is ready — payment activates your project.\n\n[[View invoice|{{invoice_url}}]]', '[\"client_name\",\"project_name\",\"invoice_url\"]', 1, '2026-09-30 20:12:56.167'),
('cmuojlbs900hcuz7de3z6cbbg', 'cmuojlaux0000uz7de9mahyza', 'invoice_sent', 'Invoice sent', 'Invoice {{invoice_number}} — {{amount}}', 'Hi {{client_name}},\n\nInvoice {{invoice_number}} for {{project_name}} is ready: {{amount}}.\n\n[[View & pay invoice|{{invoice_url}}]]', '[\"client_name\",\"project_name\",\"invoice_number\",\"amount\",\"invoice_url\"]', 1, '2026-09-30 20:12:56.169'),
('cmuojlbsd00hduz7drmz4tqcc', 'cmuojlaux0000uz7de9mahyza', 'invoice_reminder', 'Invoice reminder', 'Reminder: invoice {{invoice_number}} is due', 'Hi {{client_name}},\n\nA friendly reminder that invoice {{invoice_number}} ({{amount}}) is due.\n\n[[View & pay invoice|{{invoice_url}}]]\n\nAlready paid? Thank you — please ignore this note.', '[\"client_name\",\"invoice_number\",\"amount\",\"invoice_url\"]', 1, '2026-09-30 20:12:56.173'),
('cmuojlbsf00heuz7dzq088rm2', 'cmuojlaux0000uz7de9mahyza', 'invoice_overdue', 'Invoice overdue', 'Invoice {{invoice_number}} is overdue', 'Hi {{client_name}},\n\nInvoice {{invoice_number}} ({{amount}}) is now overdue. Please settle it when you can so we can keep your projects moving.\n\n[[View & pay invoice|{{invoice_url}}]]\n\nIf there\'s an issue, reply and we\'ll help.', '[\"client_name\",\"invoice_number\",\"amount\",\"invoice_url\"]', 1, '2026-09-30 20:12:56.175'),
('cmuojlbsj00hfuz7ddak04tdh', 'cmuojlaux0000uz7de9mahyza', 'payment_received', 'Payment received', 'Payment received — thank you', 'Hi {{client_name}},\n\nWe\'ve received your payment of {{amount}} for invoice {{invoice_number}}. Thank you!\n\n[[Open your project|{{project_url}}]]', '[\"client_name\",\"amount\",\"invoice_number\",\"project_url\"]', 1, '2026-09-30 20:12:56.179'),
('cmuojlbsl00hguz7dp2hvkfci', 'cmuojlaux0000uz7de9mahyza', 'project_started', 'Project started', 'Your project {{project_name}} has started', 'Hi {{client_name}},\n\nPayment received — {{project_name}} ({{project_id}}) is now active. Next, complete the short project setup so your editor has everything they need.\n\n[[Complete project setup|{{project_url}}]]', '[\"client_name\",\"project_name\",\"project_id\",\"project_url\"]', 1, '2026-09-30 20:12:56.181'),
('cmuojlbso00hhuz7d0eulre2m', 'cmuojlaux0000uz7de9mahyza', 'file_request', 'Action required: file request', 'Action required: {{detail}}', 'Hi {{client_name}},\n\nTo keep {{project_name}} on schedule we need: {{detail}}.\n\n[[Upload it now|{{project_url}}]]', '[\"client_name\",\"project_name\",\"detail\",\"project_url\"]', 1, '2026-09-30 20:12:56.184'),
('cmuojlbsr00hiuz7do6kf7aei', 'cmuojlaux0000uz7de9mahyza', 'draft_ready', 'Draft ready', 'Your {{version_label}} of {{project_name}} is ready to review', 'Hi {{client_name}},\n\n{{version_label}} of {{project_name}} is ready. Watch it, leave timestamped notes on the timeline, then approve it or request changes.\n\n[[Review the video|{{review_url}}]]', '[\"client_name\",\"project_name\",\"version_label\",\"review_url\"]', 1, '2026-09-30 20:12:56.187'),
('cmuojlbst00hjuz7dl7doekc6', 'cmuojlaux0000uz7de9mahyza', 'revision_received', 'Revision received', 'Revision request received — {{project_name}}', 'Hi {{client_name}},\n\nWe\'ve got your notes for {{project_name}} and your editor is on it. You\'ll be notified when the next version is ready.\n\n[[View project|{{project_url}}]]', '[\"client_name\",\"project_name\",\"project_url\"]', 1, '2026-09-30 20:12:56.189'),
('cmuojlbsw00hkuz7dfadyrcow', 'cmuojlaux0000uz7de9mahyza', 'revision_completed', 'Revision completed', 'Your revision is ready — {{project_name}}', 'Hi {{client_name}},\n\nYour revision on {{project_name}} is done — {{version_label}} is ready to review.\n\n[[Review the new version|{{review_url}}]]', '[\"client_name\",\"project_name\",\"version_label\",\"review_url\"]', 1, '2026-09-30 20:12:56.192'),
('cmuojlbsz00hluz7d6nkvgu3x', 'cmuojlaux0000uz7de9mahyza', 'approval_required', 'Final approval required', 'Final approval needed — {{project_name}}', 'Hi {{client_name}},\n\nThe final cut of {{project_name}} is ready. When you\'re happy, approve it to receive your files.\n\n[[Review & approve|{{review_url}}]]', '[\"client_name\",\"project_name\",\"review_url\"]', 1, '2026-09-30 20:12:56.195'),
('cmuojlbt100hmuz7dxw4zqt9m', 'cmuojlaux0000uz7de9mahyza', 'project_approved', 'Project approved', 'Approved — thank you, {{client_name}}', 'Hi {{client_name}},\n\nYou approved {{project_name}}. We\'re preparing your final deliverables now and will notify you as soon as they\'re ready to download.\n\n[[Open project|{{project_url}}]]', '[\"client_name\",\"project_name\",\"project_url\"]', 1, '2026-09-30 20:12:56.197'),
('cmuojlbt300hnuz7dyk1bcu7x', 'cmuojlaux0000uz7de9mahyza', 'deliverables_ready', 'Final files ready', 'Your final files are ready — {{project_name}}', 'Hi {{client_name}},\n\nYour final files for {{project_name}} are ready to download.\n\n[[Download your files|{{project_url}}]]', '[\"client_name\",\"project_name\",\"project_url\"]', 1, '2026-09-30 20:12:56.199'),
('cmuojlbt700houz7ddengw4mv', 'cmuojlaux0000uz7de9mahyza', 'project_delivered', 'Project delivered', '{{project_name}} has been delivered', 'Hi {{client_name}},\n\n{{project_name}} is complete and delivered. Thank you for working with us — need another video? Start a new project anytime and we\'ll reuse your saved brand kit.\n\n[[Start a new project|{{dashboard_url}}]]', '[\"client_name\",\"project_name\",\"dashboard_url\"]', 1, '2026-09-30 20:12:56.203'),
('cmuojlbt900hpuz7du36ewd00', 'cmuojlaux0000uz7de9mahyza', 'testimonial_request', 'Testimonial request', 'How was your experience?', 'Hi {{client_name}},\n\nThanks again for {{project_name}}. Would you share a quick rating and a line or two about working with us? We only publish feedback with your permission.\n\n[[Share feedback|{{project_url}}]]', '[\"client_name\",\"project_name\",\"project_url\"]', 1, '2026-09-30 20:12:56.205'),
('cmuojlbtd00hquz7d123fy09p', 'cmuojlaux0000uz7de9mahyza', 'retainer_renewal', 'Retainer renewal', 'Your monthly plan has renewed', 'Hi {{client_name}},\n\nYour monthly plan renewed and your new allowance is available. Your invoice {{invoice_number}} ({{amount}}) is ready.\n\n[[View invoice|{{invoice_url}}]]', '[\"client_name\",\"invoice_number\",\"amount\",\"invoice_url\"]', 1, '2026-09-30 20:12:56.209'),
('cmuojlbtg00hruz7d2604dngh', 'cmuojlaux0000uz7de9mahyza', 'new_message', 'New message', 'New message on {{project_name}}', 'Hi {{client_name}},\n\nYou have a new message:\n\n“{{message_preview}}”\n\n[[Read & reply|{{action_url}}]]', '[\"client_name\",\"project_name\",\"message_preview\",\"action_url\"]', 1, '2026-09-30 20:12:56.212'),
('cmuojlbtj00hsuz7dbkuose5h', 'cmuojlaux0000uz7de9mahyza', 'project_assigned', 'Project assigned (team)', 'You\'ve been assigned to {{project_name}}', 'Hi {{user_name}},\n\nYou\'ve been assigned to {{project_name}} ({{project_id}}).\n\n[[Open project|{{project_url}}]]', '[\"user_name\",\"project_name\",\"project_id\",\"project_url\"]', 1, '2026-09-30 20:12:56.215'),
('cmuojlbtl00htuz7d1dcz4phv', 'cmuojlaux0000uz7de9mahyza', 'notification', 'Generic notification', '{{title}}', '{{message}}\n\n[[Open in portal|{{action_url}}]]', '[\"title\",\"message\",\"action_url\"]', 1, '2026-09-30 20:12:56.217');

-- faqs: 24 row(s)
INSERT INTO `faqs` (`id`, `workspaceId`, `category`, `question`, `answer`, `serviceSlugs`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES
('cmuojlbzb00kmuz7d74ow9xvr', 'cmuojlaux0000uz7de9mahyza', 'Pricing', 'How is pricing calculated?', 'Every project gets a fixed-scope quote based on what you need: number and length of videos, complexity, deliverables and turnaround. You can also choose per-video or per-short pricing, or a monthly retainer for ongoing work. You\'ll see the full itemised price before anything starts.', '[]', 0, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00knuz7d1x1hvyyg', 'cmuojlaux0000uz7de9mahyza', 'Pricing', 'Do you offer monthly plans?', 'Yes. Retainers include a set number of videos or shorts each month with a predictable price, priority scheduling and usage tracking in your portal. Ask about a retainer when you start a project or book a call.', '[]', 10, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00kouz7dw8ifkgod', 'cmuojlaux0000uz7de9mahyza', 'Pricing', 'Is there a deposit?', 'Projects are usually started with a deposit (shown in your quote) and the balance is invoiced when you approve the final version. Your quote states the exact split.', '[]', 20, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00kpuz7d4ip33pd1', 'cmuojlaux0000uz7de9mahyza', 'Turnaround', 'How long does editing take?', 'Turnaround depends on the service and length — it\'s shown on each service page and confirmed in your quote. The clock starts when your project brief is complete and all required files are uploaded. Rush delivery may be available for an additional fee.', '[]', 30, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00kquz7dce22w24g', 'cmuojlaux0000uz7de9mahyza', 'Turnaround', 'What happens if I\'m late sending files or feedback?', 'The timeline moves with you. We\'ll always show the expected draft date in your project and remind you if we\'re waiting on something.', '[]', 40, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00kruz7dt8iz4xhr', 'cmuojlaux0000uz7de9mahyza', 'Revisions', 'How many revisions are included?', 'Your quote and contract state the included revision rounds — our standard is two. A round is one consolidated set of notes on a draft. You leave timestamped comments on the video and send them as a single revision request.', '[]', 50, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00ksuz7dy8yzde0r', 'cmuojlaux0000uz7de9mahyza', 'Revisions', 'What if I want changes after approving?', 'Approval confirms the version meets the agreed requirements. After that, further changes are treated as a new request or a change order, which we\'ll quote separately.', '[]', 60, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00ktuz7dlqcm0zyc', 'cmuojlaux0000uz7de9mahyza', 'Revisions', 'What counts as a scope change?', 'Changing the agreed deliverables, adding new footage or formats, or altering the direction after production started is a scope change. Submit a change request in your project and we\'ll classify it as included, out of scope, or quote the extra cost.', '[]', 70, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00kuuz7dlc56xse0', 'cmuojlaux0000uz7de9mahyza', 'Files', 'How do I send my footage?', 'Upload directly from your project\'s Files tab — drag and drop with a progress bar, into folders like Raw Footage, Audio, Brand Assets and Music. Large files are sent straight to secure cloud storage.', '[]', 80, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00kvuz7d5nyinfhv', 'cmuojlaux0000uz7de9mahyza', 'Files', 'What files should I send?', 'Raw footage or recordings, clean audio if recorded separately, your logo (PNG/SVG), brand colours and fonts, scripts or talking points, reference videos, and any music you want used. Your project setup form tells you exactly what\'s needed for your type of video.', '[]', 90, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00kwuz7d3nq9qtv8', 'cmuojlaux0000uz7de9mahyza', 'Files', 'Is my footage private?', 'Yes. Files are stored in access-controlled cloud storage and served through short-lived signed links. Only you, your team members and the studio staff assigned to your project can access them.', '[]', 100, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00kxuz7defmwj2s0', 'cmuojlaux0000uz7de9mahyza', 'Files', 'How long do you keep my files?', 'We keep your project files so repeat projects are fast. You can ask us to delete any project\'s files at any time.', '[]', 110, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00kyuz7dog2x62dt', 'cmuojlaux0000uz7de9mahyza', 'Payments', 'How does payment work?', 'After you accept a quote and sign the agreement, you\'ll receive an invoice in your portal. Payment activates your project. Any remaining balance is invoiced when you approve the final version.', '[]', 120, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00kzuz7d8djt1xjo', 'cmuojlaux0000uz7de9mahyza', 'Payments', 'Which currencies and payment methods do you support?', 'Quotes and invoices can be issued in multiple currencies. Available payment methods depend on the studio\'s payment provider and are shown at checkout.', '[]', 130, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00l0uz7deyz21hk1', 'cmuojlaux0000uz7de9mahyza', 'Editing', 'Can you match my existing style?', 'Yes. Save your brand kit — logos, colours, fonts and music preferences — and share reference videos. We keep your style consistent across projects.', '[]', 140, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00l1uz7dqtez4p8j', 'cmuojlaux0000uz7de9mahyza', 'Editing', 'Who edits my videos?', 'A named editor is assigned to your project and you can message them (or the project manager) right inside the project. Repeat clients keep the same editor where possible.', '[]', 150, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00l2uz7dhjivxvc5', 'cmuojlaux0000uz7de9mahyza', 'Editing', 'Do you provide the project files?', 'Final videos, captions and requested formats are always delivered. Editable source files can be included if agreed in your quote.', '[]', 160, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00l3uz7dsnxdxqye', 'cmuojlaux0000uz7de9mahyza', 'Retainers', 'How do retainer allowances work?', 'Your retainer includes a set number of videos, shorts or hours each month. Your dashboard shows what you\'ve used, what\'s left, upcoming projects and your renewal date.', '[]', 170, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00l4uz7de46zxfu8', 'cmuojlaux0000uz7de9mahyza', 'Retainers', 'Can I pause or cancel a retainer?', 'Yes — retainers can be paused or cancelled according to your agreement. Contact us or message your project manager.', '[]', 180, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00l5uz7d89ur2hi3', 'cmuojlaux0000uz7de9mahyza', 'Contracts', 'Do I need to sign a contract?', 'Yes. Each project has a short agreement covering scope, deliverables, turnaround, payment terms, revision limits, usage rights, confidentiality and cancellation. You can read, download and e-sign it from your portal.', '[]', 190, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00l6uz7dgj7c3a51', 'cmuojlaux0000uz7de9mahyza', 'Contracts', 'Who owns the final videos?', 'You do. On full payment you receive a licence to use the final deliverables for your business purposes, as described in your agreement.', '[]', 200, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00l7uz7dyg945jh8', 'cmuojlaux0000uz7de9mahyza', 'Editing', 'Can you edit podcasts with multiple cameras?', 'Yes — we sync and switch multicam footage, clean the audio and produce the full episode, a YouTube version and social clips.', '[\"podcast-editing\"]', 210, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00l8uz7d0pvui5y9', 'cmuojlaux0000uz7de9mahyza', 'Editing', 'What formats do you deliver short-form in?', '9:16 vertical by default, plus 1:1 and 4:5 on request, with captions burned in or delivered as a caption file.', '[\"short-form-video-editing\",\"ugc-editing\",\"social-media-clips\"]', 220, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423'),
('cmuojlbzc00l9uz7dwou08ume', 'cmuojlaux0000uz7de9mahyza', 'Editing', 'Can you make MLS-compliant listing videos?', 'Yes. Tell us your MLS requirements and we\'ll deliver an unbranded, compliant version alongside your branded social edits.', '[\"real-estate-video-editing\"]', 230, 1, '2026-09-30 20:12:56.423', '2026-09-30 20:12:56.423');

-- kb_articles: 6 row(s)
INSERT INTO `kb_articles` (`id`, `workspaceId`, `slug`, `title`, `content`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES
('cmuojlbzh00lauz7dri0qj1f1', 'cmuojlaux0000uz7de9mahyza', 'how-do-i-upload-footage', 'How do I upload footage?', 'Open your project and choose the **Files** tab. Drag files into the upload area (or click to browse). Pick the right folder — Raw Footage, Audio, Brand Assets and so on — and watch the progress bar. Large files upload directly to secure storage, so you can close other tabs and keep working.\n\nWhen everything is up, click **I\'ve uploaded everything** so your editor knows to start.', 'Files', 0, 1, '2026-09-30 20:12:56.429', '2026-09-30 20:12:56.429'),
('cmuojlbzj00lbuz7d72hw8ndu', 'cmuojlaux0000uz7de9mahyza', 'how-many-revisions-are-included', 'How many revisions are included?', 'The number of included revision rounds is stated in your quote, contract and project header (our standard is two). A *round* is one consolidated set of notes on a draft.\n\nLeave timestamped comments while you watch, then press **Request revision** to send them all as one round.', 'Revisions', 10, 1, '2026-09-30 20:12:56.431', '2026-09-30 20:12:56.431'),
('cmuojlbzl00lcuz7dzm3v7w72', 'cmuojlaux0000uz7de9mahyza', 'how-long-does-editing-take', 'How long does editing take?', 'Your project header shows the expected draft date. Turnaround starts once your project brief is complete and your files are uploaded. If anything is missing, you\'ll see an **Action required** card on your dashboard.', 'Turnaround', 20, 1, '2026-09-30 20:12:56.433', '2026-09-30 20:12:56.433'),
('cmuojlbzp00lduz7dhwr6xle5', 'cmuojlaux0000uz7de9mahyza', 'what-happens-after-approval', 'What happens after I approve?', 'Approving locks that version as final. If there is a remaining balance we\'ll invoice it, and once payment conditions are met your final files appear on the **Delivery** tab — masters, social cuts, captions and thumbnails — ready to download.', 'Delivery', 30, 1, '2026-09-30 20:12:56.437', '2026-09-30 20:12:56.437'),
('cmuojlbzr00leuz7dfkc6yq93', 'cmuojlaux0000uz7de9mahyza', 'what-files-should-i-send', 'What files should I send?', 'Send raw footage, separate audio if you have it, your logo (PNG or SVG), brand colours and fonts, a script or talking points, references you like, and any music. Your project setup form lists exactly what\'s needed for your type of video.', 'Files', 40, 1, '2026-09-30 20:12:56.439', '2026-09-30 20:12:56.439'),
('cmuojlbzt00lfuz7dbzpdqxf0', 'cmuojlaux0000uz7de9mahyza', 'how-does-payment-work', 'How does payment work?', '1. Accept your quote.\n2. Sign the agreement.\n3. Pay the invoice — your project starts immediately.\n4. Approve the final version and pay any remaining balance to unlock final files.', 'Payments', 50, 1, '2026-09-30 20:12:56.441', '2026-09-30 20:12:56.441');

