INSERT INTO `lead_sources` (`id`, `key`, `label`, `isSystem`) VALUES
('cmuojlazz001kuz7d7pvh74pk', 'website', 'Website', 1),
('cmuojlb01001luz7dn21snj7f', 'instagram', 'Instagram', 1),
('cmuojlb03001muz7dlxgyhg85', 'linkedin', 'LinkedIn', 1),
