('cmuojlc0s00lruz7d4lqxrldh', 'cmuojlaux0000uz7de9mahyza', 'Short-Form Batch', 'A batch of vertical clips with captions and sound design.', NULL, 'short_form', 3, 2, '[{\"title\":\"Select best moments\",\"subtasks\":[]},{\"title\":\"Cut & hook optimisation\",\"subtasks\":[]},{\"title\":\"Captions & motion\",\"subtasks\":[]},{\"title\":\"Sound design\",\"subtasks\":[]},{\"title\":\"Internal review\",\"subtasks\":[]},{\"title\":\"Export & upload for review\",\"subtasks\":[]},{\"title\":\"Revisions\",\"subtasks\":[]},{\"title\":\"Final delivery\",\"subtasks\":[]}]', '[\"Long-form source video or raw clips\",\"Brand logo (PNG or SVG)\"]', NULL, '[{\"label\":\"Vertical shorts (9:16)\",\"quantity\":10}]', '2026-09-30 20:12:56.476', '2026-09-30 20:12:56.476'),
