-- services: 14 row(s)
INSERT INTO `services` (`id`, `workspaceId`, `slug`, `title`, `shortDescription`, `description`, `categoryId`, `icon`, `useCase`, `deliverables`, `included`, `whoFor`, `exampleDeliverables`, `platforms`, `editingStyle`, `addOns`, `workflow`, `revisionPolicy`, `turnaround`, `startingPrice`, `currency`, `priceLabel`, `faqCategory`, `onboardingCategories`, `seoTitle`, `seoDescription`, `heroImage`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES
('cmuojlbx000k8uz7d2s4b8lza', 'cmuojlaux0000uz7de9mahyza', 'short-form-video-editing', 'Short-Form Editing', 'Scroll-stopping vertical edits for Reels, Shorts and TikTok — built around a strong hook and clean captions.', 'Short-form lives or dies in the first two seconds. We cut for retention: tight pacing, hook-first structure, on-brand captions, sound design and motion that support the message instead of distracting from it. Send us long recordings or raw clips and we return batches that are ready to post.', 'cmuojlbwt00k7uz7dby0zd5ts', 'smartphone', 'Creators, coaches and brands publishing several vertical videos each week.', '[\"9:16 vertical exports\",\"Animated captions\",\"Sound design & music\",\"Hook optimisation\",\"CTA animation\"]', '[\"9:16 export (plus 1:1 / 4:5 on request)\",\"Captions in your brand style\",\"Motion graphics & callouts\",\"Sound design and licensed music\",\"B-roll and transitions\",\"Colour correction\",\"Hook optimisation\",\"CTA animation\",\"Two included revision rounds\"]', '[\"Creators repurposing long videos into clips\",\"Coaches and consultants building authority\",\"Brands running organic short-form\",\"Agencies that need a reliable vertical-video partner\"]', '[\"10 Reels cut from one interview\",\"Weekly Shorts batch from your podcast\",\"Product teaser series\",\"Client testimonial snippets\"]', '[\"TikTok\",\"Instagram Reels\",\"YouTube Shorts\",\"LinkedIn clips\",\"Vertical ads\"]', 'Fast, punchy and readable on mute. We match your voice: from clean and minimal to high-energy with kinetic type.', '[\"Thumbnail / cover frames\",\"Extra formats (1:1, 4:5)\",\"Rush delivery\",\"Posting schedule & captions copy\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '48–72 hours per batch', NULL, 'USD', 'Custom quote', 'Editing', '[\"SHORT_FORM\",\"CREATOR\"]', NULL, NULL, NULL, 1, 1, 0, '2026-09-30 20:12:56.340', '2026-09-30 20:12:56.340'),
('cmuojlbx600k9uz7dwxtc5ffj', 'cmuojlaux0000uz7de9mahyza', 'youtube-video-editing', 'Long-Form YouTube', 'Retention-focused editing for YouTube: pacing, story structure, b-roll, sound and thumbnails-ready exports.', 'We edit YouTube videos to hold attention from cold open to final CTA: tightening dead air, adding pattern interrupts, layering b-roll, graphics and sound design, and keeping the story clear. Your channel style stays consistent across every upload.', 'cmuojlbwt00k7uz7dby0zd5ts', 'play', 'Channels publishing weekly or bi-weekly long-form videos.', '[\"Master 16:9 edit up to 4K\",\"Chapters & timestamps\",\"Captions / SRT file\",\"Optional thumbnail\",\"Optional Shorts cutdowns\"]', '[\"Story and pacing pass\",\"B-roll, stock and screen-recording integration\",\"Motion graphics & lower thirds\",\"Sound design, music and mix\",\"Colour correction\",\"Captions (SRT)\",\"Two included revision rounds\"]', '[\"Educators and explainers\",\"Commentary and documentary channels\",\"Business and finance creators\",\"Personal brands growing on YouTube\"]', '[\"12-minute explainer\",\"Weekly commentary episode\",\"Course lesson series\",\"Documentary-style story\"]', '[\"YouTube\"]', 'Story-first. We plan hooks, open loops and chapters so viewers stay to the end.', '[\"Thumbnail design\",\"Shorts cutdowns\",\"Title & description drafting\",\"Channel style guide\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '3–5 business days', NULL, 'USD', 'Custom quote', 'Editing', '[\"CREATOR\",\"YOUTUBE\"]', NULL, NULL, NULL, 1, 1, 10, '2026-09-30 20:12:56.346', '2026-09-30 20:12:56.346'),
('cmuojlbxb00kauz7dag0gtxds', 'cmuojlaux0000uz7de9mahyza', 'podcast-editing', 'Podcast Editing', 'Full-episode video and audio edits, multicam switching, cleanup, and social clips from every recording.', 'We turn raw recordings into polished episodes: multicam switching, noise and level cleanup, filler-word trimming, intros and outros, plus vertical clips for social. One recording becomes a full episode, a YouTube cut and a week of clips.', 'cmuojlbwt00k7uz7dby0zd5ts', 'mic', 'Video and audio podcasts that want a consistent release cadence.', '[\"Full episode (video + audio)\",\"YouTube version\",\"Social clips\",\"Audio cleanup\",\"Captions\"]', '[\"Multicam switching & sync\",\"Audio cleanup & levelling\",\"Intro / outro placement\",\"Chapters and show-note timestamps\",\"Captions\",\"Highlight clips\",\"Two included revision rounds\"]', '[\"Interview and co-hosted shows\",\"Branded company podcasts\",\"Podcasters moving to video\"]', '[\"Full episode + 3 clips\",\"Audio-only feed\",\"YouTube cut with chapters\"]', '[\"YouTube\",\"Spotify\",\"Apple Podcasts\",\"Instagram\",\"TikTok\",\"LinkedIn\"]', 'Clean, natural and conversation-first — the edit should disappear.', '[\"Show notes & titles\",\"Thumbnail design\",\"Audiograms\",\"Extra clips\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '3–4 business days per episode', NULL, 'USD', 'Custom quote', 'Editing', '[\"PODCAST\"]', NULL, NULL, NULL, 1, 1, 20, '2026-09-30 20:12:56.351', '2026-09-30 20:12:56.351'),
('cmuojlbxi00kbuz7dapyw49yr', 'cmuojlaux0000uz7de9mahyza', 'real-estate-video-editing', 'Real Estate Video', 'Cinematic listing tours, agent intros and social reels — branded, fast and MLS-friendly.', 'Properties sell faster when the video feels premium. We edit walkthroughs, cinematic tours, drone sequences and agent-branded reels with clean colour, smooth transitions and on-screen details that matter to buyers.', 'cmuojlbwt00k7uz7dby0zd5ts', 'home', 'Agents, brokerages and photographers delivering listing videos at pace.', '[\"Horizontal tour\",\"Vertical social reel\",\"MLS-compliant version\",\"Agent branding\",\"Music-licensed exports\"]', '[\"Colour correction & sky/exposure fixes\",\"Agent branding and lower thirds\",\"Drone and interior sequencing\",\"Licensed music\",\"Horizontal and vertical exports\",\"Two included revision rounds\"]', '[\"Real-estate agents and teams\",\"Property photographers and videographers\",\"Luxury developers and short-let hosts\"]', '[\"90-second listing tour\",\"30-second Instagram reel\",\"Agent introduction + featured listing\"]', '[\"MLS\",\"YouTube\",\"Instagram\",\"Facebook\",\"TikTok\"]', 'Bright, clean and cinematic — smooth movement, honest colour, no gimmicks.', '[\"Twilight sky replacement\",\"Neighbourhood highlight\",\"Floor-plan animation\",\"Rush delivery\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '24–72 hours per listing', NULL, 'USD', 'Custom quote', 'Editing', '[\"REAL_ESTATE\"]', NULL, NULL, NULL, 1, 1, 30, '2026-09-30 20:12:56.358', '2026-09-30 20:12:56.358'),
('cmuojlbxp00kcuz7d7m1n4sja', 'cmuojlaux0000uz7de9mahyza', 'corporate-video-editing', 'Corporate Video', 'Brand films, internal comms, training and executive messages — polished and on-brand.', 'We edit corporate content with an eye for clarity and brand consistency: interviews, explainers, training modules, recruitment and event recaps, all aligned to your guidelines and review process.', 'cmuojlbwt00k7uz7dby0zd5ts', 'building', 'Marketing and comms teams that need reliable, brand-safe video.', '[\"Master edit\",\"Brand-compliant graphics\",\"Captions\",\"Alt cutdowns\",\"Source files (if agreed)\"]', '[\"Interview editing\",\"Brand graphics & lower thirds\",\"Captions & accessibility\",\"Stakeholder review workflow\",\"Two included revision rounds\"]', '[\"Marketing and communications teams\",\"HR & L&D departments\",\"Agencies serving corporate clients\"]', '[\"Brand film\",\"Training module series\",\"Executive update\",\"Event recap\"]', '[\"Website\",\"LinkedIn\",\"Intranet\",\"YouTube\"]', 'Polished, calm and credible.', '[\"Multiple language captions\",\"Cutdowns for social\",\"Legal/brand review rounds\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '5–7 business days', NULL, 'USD', 'Custom quote', 'Contracts', '[\"CORPORATE\"]', NULL, NULL, NULL, 1, 0, 40, '2026-09-30 20:12:56.366', '2026-09-30 20:12:56.366'),
('cmuojlbxw00kduz7ddp011h7n', 'cmuojlaux0000uz7de9mahyza', 'saas-video-editing', 'SaaS / Product Video', 'Product demos, explainers and launch videos with clean UI animation and clear storytelling.', 'We turn screen recordings and product footage into clear, compelling stories: focused zooms and callouts, UI animations, voiceover sync and motion graphics that explain what your product does in seconds.', 'cmuojlbwt00k7uz7dby0zd5ts', 'monitor', 'Startups and SaaS teams launching features, demos and onboarding videos.', '[\"Product demo\",\"Explainer\",\"Feature announcement\",\"Onboarding tutorial\",\"Social cutdowns\"]', '[\"Screen-recording polish\",\"UI animation & callouts\",\"Voiceover sync\",\"Captions\",\"Brand-consistent motion graphics\",\"Two included revision rounds\"]', '[\"Product-led SaaS companies\",\"Early-stage founders\",\"Customer-success and onboarding teams\"]', '[\"60-second product demo\",\"Feature launch video\",\"Onboarding walkthrough\"]', '[\"Website\",\"Product Hunt\",\"YouTube\",\"LinkedIn\",\"In-app\"]', 'Crisp, modern and focused on outcomes, not features.', '[\"AI or human voiceover\",\"Product mockup animation\",\"Localised versions\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '4–6 business days', NULL, 'USD', 'Custom quote', 'Editing', '[\"SAAS\"]', NULL, NULL, NULL, 1, 0, 50, '2026-09-30 20:12:56.372', '2026-09-30 20:12:56.372'),
('cmuojlby200keuz7dml6p319o', 'cmuojlaux0000uz7de9mahyza', 'vsl-editing', 'VSL Editing', 'Direct-response video sales letters with persuasive pacing, proof and clear calls to action.', 'A great VSL keeps attention and moves viewers toward one action. We structure pacing, on-screen text, proof elements and pattern interrupts around your script so the message lands and the offer is clear.', 'cmuojlbwt00k7uz7dby0zd5ts', 'megaphone', 'Coaches, info-product owners and DTC brands running direct-response funnels.', '[\"VSL master\",\"Text-on-screen version\",\"Alternate hooks\",\"Captions\"]', '[\"Script-based structure\",\"On-screen text & emphasis\",\"Proof and testimonial integration\",\"Sound design & music\",\"Two included revision rounds\"]', '[\"Info-product and course creators\",\"Coaches & consultants\",\"Direct-response marketers\"]', '[\"12-minute VSL\",\"Hook A/B variants\",\"Mobile-first cut\"]', '[\"Landing pages\",\"Funnels\",\"Paid social\"]', 'Clear, persuasive and paced for attention.', '[\"Extra hook variants\",\"Voiceover\",\"Stock & b-roll sourcing\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '5–8 business days', NULL, 'USD', 'Custom quote', 'Editing', '[\"VSL\"]', NULL, NULL, NULL, 1, 0, 60, '2026-09-30 20:12:56.378', '2026-09-30 20:12:56.378'),
('cmuojlby700kfuz7d53dh3pzz', 'cmuojlaux0000uz7de9mahyza', 'ugc-editing', 'UGC Editing', 'Authentic, high-converting UGC-style edits for paid social and organic.', 'We polish creator-shot footage into native-feeling ads and posts: tight hooks, captions, b-roll, product overlays and multiple hook variations for testing.', 'cmuojlbwt00k7uz7dby0zd5ts', 'users', 'E-commerce and DTC brands testing creative at volume.', '[\"Vertical UGC edits\",\"Hook variations\",\"Captions\",\"Product overlays\"]', '[\"Hook variations\",\"Native-style captions\",\"B-roll & product inserts\",\"Audio cleanup\",\"Two included revision rounds\"]', '[\"DTC and e-commerce brands\",\"Performance marketing teams\",\"UGC creators\"]', '[\"5 UGC ad variations\",\"Unboxing edit\",\"Testimonial ad\"]', '[\"TikTok\",\"Instagram\",\"Meta Ads\",\"YouTube Shorts\"]', 'Native, raw and trustworthy — never over-produced.', '[\"Extra hooks\",\"Static thumbnails\",\"Rush delivery\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '48–72 hours', NULL, 'USD', 'Custom quote', 'Editing', '[\"ECOMMERCE\",\"ADS\",\"SHORT_FORM\"]', NULL, NULL, NULL, 1, 0, 70, '2026-09-30 20:12:56.383', '2026-09-30 20:12:56.383'),
('cmuojlbyc00kguz7d3w77p6n9', 'cmuojlaux0000uz7de9mahyza', 'social-media-clips', 'Social Media Clips', 'Turn webinars, streams and long videos into a steady stream of on-brand clips.', 'We find the moments worth sharing and format them for every platform, with captions, branding and titles — so one recording feeds your whole content calendar.', 'cmuojlbwt00k7uz7dby0zd5ts', 'share', 'Teams repurposing webinars, interviews and events.', '[\"Clip packs\",\"Captions\",\"Multi-format exports\",\"Titles\"]', '[\"Moment selection\",\"Captions & branding\",\"Multi-format exports\",\"Two included revision rounds\"]', '[\"Marketing teams\",\"Coaches with recorded calls\",\"Event organisers\"]', '[\"10 clips from a webinar\",\"Event highlights\"]', '[\"LinkedIn\",\"Instagram\",\"TikTok\",\"YouTube Shorts\",\"X\"]', 'Clean and consistent with your brand.', '[\"Posting copy\",\"Extra formats\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '2–4 business days', NULL, 'USD', 'Custom quote', 'Editing', '[\"SOCIAL\",\"SHORT_FORM\"]', NULL, NULL, NULL, 1, 0, 80, '2026-09-30 20:12:56.388', '2026-09-30 20:12:56.388'),
('cmuojlbyi00khuz7d3vkz91mn', 'cmuojlaux0000uz7de9mahyza', 'motion-graphics', 'Motion Graphics', 'Logo animations, lower thirds, kinetic type and explainers that lift any video.', 'Custom motion design that matches your identity: animated logos, title systems, lower thirds, data visuals and short explainers — delivered as finished video and, where agreed, editable project files.', 'cmuojlbwt00k7uz7dby0zd5ts', 'sparkles', 'Brands and creators who want a distinct, consistent motion language.', '[\"Logo animation\",\"Title packages\",\"Lower thirds\",\"Explainer animation\",\"Project files (if agreed)\"]', '[\"Storyboard / style frames\",\"Animation\",\"Sound design\",\"Export in requested formats\",\"Two included revision rounds\"]', '[\"Brands building a motion identity\",\"Creators wanting reusable graphics\",\"Agencies\"]', '[\"5-second logo sting\",\"Animated lower-third pack\",\"45-second explainer\"]', '[\"All platforms\"]', 'Smooth, precise and brand-true.', '[\"Editable templates\",\"Alpha-channel exports\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '4–7 business days', NULL, 'USD', 'Custom quote', 'Editing', '[\"MOTION\"]', NULL, NULL, NULL, 1, 0, 90, '2026-09-30 20:12:56.394', '2026-09-30 20:12:56.394'),
('cmuojlbyn00kiuz7d8y5yflb6', 'cmuojlaux0000uz7de9mahyza', 'talking-head-editing', 'Talking Head Editing', 'Crisp jump-cuts, captions and light graphics for founder, coach and expert-led videos.', 'Great talking-head videos feel effortless. We tighten delivery, remove filler, add light motion and captions, and keep your personality intact.', 'cmuojlbwt00k7uz7dby0zd5ts', 'video', 'Founders, coaches and experts publishing regularly to camera.', '[\"Edited video\",\"Captions\",\"Light graphics\",\"Audio cleanup\"]', '[\"Filler and silence removal\",\"Captions\",\"Audio cleanup\",\"Light motion & zooms\",\"Two included revision rounds\"]', '[\"Founders & executives\",\"Coaches & consultants\",\"Educators\"]', '[\"Weekly talking-head episode\",\"Founder update\",\"Course lesson\"]', '[\"YouTube\",\"LinkedIn\",\"Instagram\",\"Website\"]', 'Natural and tight, with purposeful emphasis.', '[\"Thumbnails\",\"Clip cutdowns\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '2–3 business days', NULL, 'USD', 'Custom quote', 'Editing', '[\"CREATOR\",\"COACHING\"]', NULL, NULL, NULL, 1, 0, 100, '2026-09-30 20:12:56.399', '2026-09-30 20:12:56.399'),
('cmuojlbys00kjuz7drqg5x9j5', 'cmuojlaux0000uz7de9mahyza', 'gaming-content-editing', 'Gaming Content', 'High-energy gameplay edits: highlights, memes, sound effects and vertical clips.', 'We turn hours of gameplay and stream footage into entertaining videos: highlight reels, comedic edits, montage sequences and vertical clips, with sound design that hits.', 'cmuojlbwt00k7uz7dby0zd5ts', 'gamepad', 'Streamers and gaming channels growing on YouTube and Shorts.', '[\"Highlight videos\",\"Vertical clips\",\"Facecam layouts\",\"Thumbnails (optional)\"]', '[\"Moment selection\",\"Sound effects & music\",\"Facecam integration\",\"Captions & memes\",\"Two included revision rounds\"]', '[\"Streamers\",\"Gaming channels\",\"Esports teams\"]', '[\"Weekly highlight video\",\"Clip batch from a stream\"]', '[\"YouTube\",\"Twitch\",\"TikTok\",\"Shorts\"]', 'Fast, funny and loud.', '[\"Thumbnail design\",\"Stream-to-shorts pipeline\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '3–5 business days', NULL, 'USD', 'Custom quote', 'Editing', '[\"GAMING\",\"CREATOR\"]', NULL, NULL, NULL, 1, 0, 110, '2026-09-30 20:12:56.404', '2026-09-30 20:12:56.404'),
('cmuojlbyx00kkuz7d4otjp8wp', 'cmuojlaux0000uz7de9mahyza', 'event-video-editing', 'Event Editing', 'Weddings, conferences and launches turned into highlight films and social teasers.', 'We edit event footage into emotional, well-paced films: highlight reels, full ceremonies, speeches and quick social teasers — with careful audio and colour.', 'cmuojlbwt00k7uz7dby0zd5ts', 'calendar', 'Videographers and organisers who need dependable post-production.', '[\"Highlight film\",\"Full-length edit\",\"Teasers\",\"Speech edits\"]', '[\"Multicam sync\",\"Audio cleanup\",\"Colour grading\",\"Music licensing\",\"Two included revision rounds\"]', '[\"Wedding & event videographers\",\"Conference organisers\",\"Brands hosting launches\"]', '[\"4-minute wedding highlight\",\"Conference recap\",\"Social teaser\"]', '[\"YouTube\",\"Vimeo\",\"Instagram\",\"Website\"]', 'Cinematic, warm and story-led.', '[\"Same-day teaser\",\"Extra formats\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '5–10 business days', NULL, 'USD', 'Custom quote', 'Editing', '[\"WEDDING\"]', NULL, NULL, NULL, 1, 0, 120, '2026-09-30 20:12:56.409', '2026-09-30 20:12:56.409'),
('cmuojlbz100kluz7d0705hye4', 'cmuojlaux0000uz7de9mahyza', 'ad-creative-editing', 'Ad Creative Editing', 'Performance-focused ad edits with fast iteration on hooks, formats and calls to action.', 'We produce ad creative built to be tested: multiple hooks, formats and lengths, with clear offers, captions and CTAs — organised so your media buyer can launch quickly.', 'cmuojlbwt00k7uz7dby0zd5ts', 'target', 'Performance teams that need volume and speed in creative testing.', '[\"Ad variations\",\"Multiple aspect ratios\",\"Captions\",\"Hook tests\"]', '[\"Hook variations\",\"Multi-format exports\",\"Captions & overlays\",\"Brand safety checks\",\"Two included revision rounds\"]', '[\"Performance marketers\",\"E-commerce brands\",\"Agencies\"]', '[\"6 hook variants of one concept\",\"Retargeting cutdowns\"]', '[\"Meta\",\"TikTok\",\"YouTube\",\"Google\"]', 'Direct, clear and built for testing.', '[\"Static cutdowns\",\"Rush delivery\"]', '[\"Send your footage and brief through your portal\",\"We confirm scope and timeline in a fixed-price quote\",\"Your editor delivers a first draft for timestamped review\",\"Request revisions directly on the timeline\",\"Approve the final version and download all files\"]', NULL, '2–4 business days', NULL, 'USD', 'Custom quote', 'Editing', '[\"ADS\",\"ECOMMERCE\"]', NULL, NULL, NULL, 1, 0, 130, '2026-09-30 20:12:56.413', '2026-09-30 20:12:56.413');

